package com.focusflow.api.service; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.entity.Category; import com.focusflow.api.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*; @Service public class CategoryService {final CategoryRepository cats;final UserRepository users;public CategoryService(CategoryRepository c,UserRepository u){cats=c;users=u;} CategoryResponse map(Category c){return new CategoryResponse(c.id,c.name,c.color);} Category owned(String id,String u){return cats.findByIdAndUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Category not found"));} public List<CategoryResponse> all(String u){return cats.findByUserId(u).stream().map(this::map).toList();} public CategoryResponse create(CategoryRequest r,String u){var c=new Category();c.user=users.getReferenceById(u);c.name=r.name();if(r.color()!=null)c.color=r.color();return map(cats.save(c));} public CategoryResponse update(String id,CategoryRequest r,String u){var c=owned(id,u);c.name=r.name();if(r.color()!=null)c.color=r.color();return map(cats.save(c));} public void delete(String id,String u){cats.delete(owned(id,u));} }
